import { products, testimonials, contacts } from './products.js';

const assets = await fetch('/asset-map.json').then(r=>r.json());
const app = document.querySelector('#app');
const slug = location.pathname.replace(/^\/+|\/+$/g,'');
const product = products.find(p=>p.slug===slug);
const arrow = '<svg width="20" height="20" viewBox="0 0 24 24" fill="none" aria-hidden="true"><path d="M5 12h14m-6-6 6 6-6 6" stroke="currentColor" stroke-width="1.6"/></svg>';
const diagonal = '<svg width="22" height="22" viewBox="0 0 24 24" fill="none" aria-hidden="true"><path d="M6 18 18 6M6 6h12v12" stroke="currentColor" stroke-width="1.5"/></svg>';
const check = '<svg width="16" height="16" viewBox="0 0 20 20" fill="none" aria-hidden="true"><path d="m4 10 4 4 8-8" stroke="currentColor" stroke-width="1.6"/></svg>';
const esc = s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const img = p=>assets.products?.[p.slug]||{};
const image = (src,alt,cls='',eager=false)=>`<img src="${esc(src)}" alt="${esc(alt)}" class="${cls}" ${eager?'fetchpriority="high"':'loading="lazy"'} decoding="async">`;
const button = (text,href,cls='primary')=>`<a class="button ${cls}" href="${href}">${text}${arrow}</a>`;
const label = (n,text)=>`<div class="eyebrow section-label"><span>${n}</span>${text}</div>`;
const sectionHead = (n,kicker,title,extra='')=>`<div class="section-head"><div>${label(n,kicker)}<h2>${title}</h2></div>${extra}</div>`;

function header(){return `<header class="header"><div class="container header-inner"><a class="brand" href="/" aria-label="DGSHAPE — головна">${image(assets.logo,'DGSHAPE','',true)}</a><nav class="desktop-nav" aria-label="Основна навігація"><a href="/#frezery">Фрезери</a><a href="/#tekhnolohii">Технології</a><a href="/#vidhuky">Відгуки</a><a href="/#kontakty">Контакти</a></nav><div class="header-actions"><a class="header-cta" href="${product?'#konsultatsiia':'/#konsultatsiia'}">Отримати пропозицію ${diagonal}</a><button class="menu-toggle" aria-label="Відкрити меню" aria-expanded="false" aria-controls="mobile-nav"><span></span><span></span></button></div></div><nav id="mobile-nav" class="mobile-nav" aria-label="Мобільна навігація" hidden><a href="/#frezery">Фрезери ${arrow}</a><a href="/#tekhnolohii">Технології ${arrow}</a><a href="/#vidhuky">Відгуки ${arrow}</a><a href="/#kontakty">Контакти ${arrow}</a><a href="${product?'#konsultatsiia':'/#konsultatsiia'}">Отримати пропозицію ${arrow}</a><p>Yamamoto Dental Group<br>Японські технології. Поруч з вами.</p></nav></header>`;}

function hero(){const p=products.find(p=>p.slug==='dwx53d');return `<section class="hero"><div class="container hero-inner"><div class="hero-copy"><div class="eyebrow light"><i></i>Японські CAD/CAM-фрезери DGSHAPE</div><h1>Точність, <br>що формує <br><span>результат.</span></h1><p>Рішення для зуботехнічних лабораторій та стоматологічних клінік. Оберіть фрезер під свої матеріали, задачі та обсяги роботи.</p><div class="hero-buttons">${button('Переглянути фрезери','#frezery')}${button('Отримати консультацію','#konsultatsiia','text-light')}</div></div><div class="hero-visual"><div class="precision-grid" aria-hidden="true"></div><div class="hero-ring" aria-hidden="true"></div><span class="hero-word" aria-hidden="true">53D</span>${image(img(p).hero,'DGSHAPE DWX-53D — оригінальний вигляд фрезера','hero-machine',true)}<a href="/dwx53d" class="hero-product"><span><small>Інженерія в кожній деталі</small><strong>DWX-53D</strong></span><span class="round-arrow">${diagonal}</span></a><span class="hero-marker"><i></i>5-осьова точність</span></div><div class="hero-bottom"><span>Інженерія Японії. Можливості для вашої практики.</span><a href="#frezery">Відкрийте можливості <span>↓</span></a></div></div></section><div class="trust-band"><div class="container trust-inner"><span><i></i>DGSHAPE / ROLAND</span><span>Відкрита CAD/CAM-система</span><span>Для лабораторій та клінік</span><span>Yamamoto Dental Group</span></div></div>`;}

function card(p,index){return `<article class="product-card reveal"><a class="card-visual" href="/${p.slug}" aria-label="Детальніше про ${p.name}"><div class="card-top"><span class="tag ${p.slug==='dwx43w'?'wet':''}"><i></i>${p.mode}</span><span class="card-index">0${index+1}</span></div><span class="card-watermark" aria-hidden="true">${p.name.replace('DWX-','').replace(' Plus','')}</span>${image(img(p).card||img(p).hero,p.name)}<span class="visual-link">${diagonal}</span></a><div class="card-content"><div class="card-title"><h3><a href="/${p.slug}">${p.name}</a></h3><span>${p.axes} ос${p.axes===5?'ей':'і'}</span></div><p>${p.positioning}</p><ul class="card-features">${p.cardFeatures.map(f=>`<li>${check}${f}</li>`).join('')}</ul><a class="text-link" href="/${p.slug}">Детальніше про модель ${arrow}</a></div></article>`;}
function lineup(){return `<section id="frezery" class="section container">${sectionHead('01','Лінійка фрезерів','Чотири моделі.<br>Ваше точне рішення.','<p class="section-intro">Від щоденних реставрацій до<br>автоматизованого виробництва.<br>Знайдіть свій DGSHAPE.</p>')}<div class="product-grid">${products.map(card).join('')}</div></section>`;}

const compareRows = [
 ['Тип обробки',['Суха','Мокра','Суха','Суха']],
 ['Кількість осей',['5 осей','4 осі','5 осей','5 осей']],
 ['Інструменти',['15 · автоматична зміна','До 6 інструментів¹','15 · автоматична зміна','15 · автоматична зміна']],
 ['Робота із заготовками',['Диск · C-Clamp','До 6 пін-блоків у холдері','Диск · Open Edge Adapter','До 6 дисків · автоматична зміна']],
 ['Основний фокус',['Широкий вибір сухих матеріалів','Склокераміка та преміли²','Гнучкість і віддалений контроль','Тривалі автоматизовані цикли']]
];
function comparison(){return `<section id="porivniannia" class="section compare-section"><div class="container">${sectionHead('02','Порівняння','Який фрезер підходить<br>вашим задачам?',button('Допоможіть обрати','#konsultatsiia','outline'))}<div class="comparison-desktop"><table><caption class="sr-only">Порівняння чотирьох CAD/CAM-фрезерів DGSHAPE</caption><thead><tr><th scope="col">Оберіть за можливостями</th>${products.map(p=>`<th scope="col"><a href="/${p.slug}">${p.name}${diagonal}</a></th>`).join('')}</tr></thead><tbody>${compareRows.map(([k,v])=>`<tr><th scope="row">${k}</th>${v.map(x=>`<td>${x}</td>`).join('')}</tr>`).join('')}</tbody></table></div><div class="comparison-mobile">${products.map((p,i)=>`<article><h3><a href="/${p.slug}">${p.name}${diagonal}</a></h3><dl>${compareRows.map(([k,v])=>`<div><dt>${k}</dt><dd>${v[i]}</dd></div>`).join('')}</dl></article>`).join('')}</div><p class="footnote">¹ Для DWX-43W у джерелі вказана кількість фрез; тип їх зміни потребує підтвердження. ² Титанові преміли — з додатковим холдером, який продається окремо. Зміна інструментів і зміна заготовок — різні функції.</p></div></section>`;}

function technology(){return `<section id="tekhnolohii" class="section container">${sectionHead('03','Технології DGSHAPE','Точність —<br>у кожній деталі.','<p class="section-intro">Продумана механіка.<br>Контрольований процес.<br>Більше уваги до результату.</p>')}<div class="technology-layout"><figure class="technology-photo reveal">${image(assets.technology||img(products.find(p=>p.slug==='dwx53d')).detail,'Робоча камера та фрезерувальний механізм DGSHAPE DWX-53D')}<figcaption><span>DWX-53D / Робочий процес</span><span>Інженерія зблизька ${diagonal}</span></figcaption></figure><div class="technology-points"><article><span>01 / Система</span><h3>Свобода цифрового процесу</h3><p>Відкрита архітектура лінійки дозволяє інтегрувати фрезер у роботу з вашим сканером та програмним забезпеченням.</p></article><article><span>02 / Деталі</span><h3>Доступ до складної анатомії</h3><p>Open Edge Adapter у DWX-53D відкриває можливості для обробки піднутрень і тонких анатомічних елементів. Адаптер входить у стандартну комплектацію цієї моделі.</p></article><article><span>03 / Автоматизація</span><h3>Робота на кілька кроків уперед</h3><p>DWX-53DC автоматично змінює до 6 дисків і окремо — 15 інструментів. Вбудована камера дає змогу віддалено стежити за процесом.</p></article></div></div></section>`;}

function reviews(){return `<section id="vidhuky" class="section reviews-section"><div class="container">${sectionHead('04','Досвід професіоналів','Точність, яку цінують<br>у щоденній роботі.','<p class="section-intro">Досвід українських лабораторій<br>та фрезерних центрів.</p>')}<div class="reviews-grid">${testimonials.map((r,i)=>`<article class="review reveal"><span class="quote-mark" aria-hidden="true">“</span><p>${esc(r.text)}</p><div class="review-author"><span class="avatar">${r.author.split(' ').map(s=>s[0]).slice(0,2).join('')}</span><div><h3>${esc(r.author)}</h3><span>${esc(r.organization)} · ${esc(r.city)}</span></div></div><small>Стислий переказ відгуку на roland.dental</small></article>`).join('')}</div></div></section>`;}

function consultation(p){return `<section id="konsultatsiia" class="consultation"><div class="container consultation-grid"><div class="consultation-copy">${label('05','Почнемо з ваших задач')}<h2>${p?'Ваш наступний крок —<br>власний '+p.name+'.':'Підберемо фрезер<br>під ваші задачі.'}</h2><p>Матеріали, типи реставрацій, обсяг роботи.<br>Знайдемо рішення, що відповідає вашій практиці.</p><div class="dealer"><div><strong>Yamamoto Dental Group</strong><span>Компанія-дилер DGSHAPE / Roland</span></div></div><div id="kontakty" class="contact-details"><a href="tel:+380443343834">+38 044 334 38 34 ${diagonal}</a><a href="mailto:info@yamamoto.com.ua">info@yamamoto.com.ua ${diagonal}</a><p>вул. Волинська, 67, м. Київ</p><details><summary>Інші телефони</summary><a href="tel:+380443343835">+38 044 334 38 35</a><a href="tel:+380633742477">+38 063 374 24 77</a><a href="tel:+380954720836">+38 095 472 08 36</a><a href="tel:+380965105301">+38 096 510 53 01</a></details></div></div><form class="consultation-form"><div class="form-heading"><h3>Обговорімо ваше рішення</h3><span class="demo-tag">Тестова форма</span></div><p class="form-note" id="form-note">Демонстрація прототипу. Дані не надсилаються та не зберігаються.</p><div class="field-row"><label>Ім’я<input name="name" autocomplete="given-name" placeholder="Як до вас звертатися?" required maxlength="80"></label><label>Телефон<input name="phone" type="tel" autocomplete="tel" placeholder="+380 __ ___ __ __" required inputmode="tel" maxlength="25"></label></div><label>Модель<select name="model" id="model" aria-label="Модель"><option value="help" ${!p?'selected':''}>Потрібна допомога з вибором</option>${products.map(x=>`<option value="${x.slug}" ${p?.slug===x.slug?'selected':''}>${x.name}</option>`).join('')}</select></label><label>Коментар <span class="optional">(необов’язково)</span><textarea name="comment" placeholder="З якими матеріалами та задачами працюєте?" rows="3" maxlength="1500"></textarea></label><button type="submit" class="button primary">Перевірити тестову форму ${arrow}</button><div class="form-feedback" role="status" aria-live="polite"></div><p class="form-bottom">Для реального звернення скористайтеся телефоном або email компанії.</p></form></div></section>`;}

function footer(){return `<footer class="footer"><div class="container footer-top"><a href="/" class="brand" aria-label="DGSHAPE — головна">${image(assets.logo,'DGSHAPE')}</a><span>Японські технології.<br>Точність без компромісів.</span><a href="/#frezery">Усі фрезери ${arrow}</a><a href="/#kontakty">Контакти ${arrow}</a></div><div class="container footer-bottom"><span>© ${new Date().getFullYear()} Yamamoto Dental Group</span><span>Демонстраційний прототип · Тестові форми</span><a href="#main">Нагору ↑</a></div></footer>`;}

function productHero(p){return `<section class="product-hero"><div class="container"><div class="breadcrumbs"><a href="/">Головна</a><span>/</span><a href="/#frezery">Фрезери</a><span>/</span><span>${p.name}</span></div><div class="product-hero-grid"><div class="product-copy"><div class="eyebrow light"><i></i>${p.mode} · ${p.axes} ос${p.axes===5?'ей':'і'}</div><h1>${p.name.replace(' Plus',' <span class="plus">Plus</span>')}</h1><h2>${p.positioning}</h2><p>${p.description}</p>${button('Отримати пропозицію','#konsultatsiia')}<a class="back-link" href="/#frezery">← Усі фрезери</a></div><div class="product-hero-visual"><div class="hero-ring" aria-hidden="true"></div>${image(img(p).hero,p.name,p.slug==='dwx53d'?'reflective':'',true)}<span class="product-visual-caption">DGSHAPE / Японська інженерія</span></div></div></div></section><nav class="product-subnav" aria-label="Розділи продукту"><div class="container"><strong>${p.name}</strong><a href="#osoblyvosti">Особливості</a><a href="#halereia">Галерея</a><a href="#materialy">Матеріали</a><a href="#kharakterystyky">Характеристики</a><a href="#konsultatsiia">Консультація ${arrow}</a></div></nav>`;}

function productFeatures(p){return `<section id="osoblyvosti" class="section container">${sectionHead('01','Можливості моделі','Створений для<br>вашого результату.')}<div class="features-grid">${p.features.map((f,i)=>`<article class="feature reveal"><span class="feature-number">0${i+1}</span><h3>${f.title}</h3><p>${f.text}</p></article>`).join('')}</div></section>`;}
function gallery(p){let images=img(p).gallery?.length?img(p).gallery:[img(p).hero]; return `<section id="halereia" class="section gallery-section"><div class="container">${sectionHead('02','Ближче до інженерії','Розгляньте кожну деталь.')}<div class="gallery-main"><button class="gallery-enlarge" aria-label="Збільшити фото ${p.name}">${image(images[0],p.name+' — фото 1','gallery-current')}<span class="gallery-zoom">${diagonal} Збільшити</span></button><span class="gallery-counter">01 / ${String(images.length).padStart(2,'0')}</span></div><div class="gallery-thumbs" aria-label="Фотографії ${p.name}">${images.map((src,i)=>`<button class="gallery-thumb ${i===0?'active':''}" data-src="${esc(src)}" data-index="${i}" aria-label="Показати фото ${i+1}" aria-pressed="${i===0}">${image(src,p.name+' — ракурс '+(i+1))}</button>`).join('')}${p.video?`<button class="video-button" data-video="${esc(p.video)}"><span>▷</span>Дивитися відео</button>`:''}</div></div></section>`;}
function materials(p){return `<section id="materialy" class="section container materials-layout"><div>${label('03','Матеріали та задачі')}<h2>Від матеріалу —<br>до реставрації.</h2><p class="section-intro">Можливості ${p.name}<br>для вашого цифрового процесу.</p></div><div><h3 class="minor-heading">Матеріали для обробки</h3><ul class="material-tags">${p.materials.map(x=>`<li>${x}</li>`).join('')}</ul><h3 class="minor-heading">Для ваших задач</h3><ul class="task-list">${p.tasks.map(x=>`<li>${check}${x}</li>`).join('')}</ul>${p.caveat?`<p class="caveat"><span>i</span>${p.caveat}</p>`:''}</div></section>`;}
function specs(p){return `<section id="kharakterystyky" class="section specs-section"><div class="container specs-layout"><div>${label('04','Технічні дані')}<h2>Точні деталі.<br>Зважений вибір.</h2><p class="section-intro">Ключові характеристики ${p.name}.</p></div><div><dl class="spec-list">${p.specs.map(([k,v])=>`<div><dt>${k}</dt><dd>${v}</dd></div>`).join('')}</dl><p class="footnote">Параметри наведені за сторінкою моделі на roland.dental. Остаточну комплектацію та сумісність матеріалів уточнюйте в Yamamoto Dental Group.</p></div></div></section>`;}

app.innerHTML=header()+`<main id="main">`+(product?productHero(product)+productFeatures(product)+gallery(product)+materials(product)+specs(product)+consultation(product):hero()+lineup()+comparison()+technology()+reviews()+consultation())+`</main>`+footer()+`<dialog class="lightbox" aria-label="Перегляд зображення"><button class="lightbox-close" aria-label="Закрити перегляд">✕</button><button class="lightbox-prev" aria-label="Попереднє фото">←</button><div class="lightbox-content"></div><button class="lightbox-next" aria-label="Наступне фото">→</button><p class="lightbox-caption"></p></dialog>`;

const menuButton=document.querySelector('.menu-toggle'), mobileMenu=document.querySelector('.mobile-nav');
function closeMenu(){menuButton.setAttribute('aria-expanded','false');menuButton.setAttribute('aria-label','Відкрити меню');mobileMenu.hidden=true;document.body.classList.remove('menu-open');}
menuButton.addEventListener('click',()=>{const open=menuButton.getAttribute('aria-expanded')==='true';menuButton.setAttribute('aria-expanded',String(!open));menuButton.setAttribute('aria-label',open?'Відкрити меню':'Закрити меню');mobileMenu.hidden=open;document.body.classList.toggle('menu-open',!open);});
mobileMenu.querySelectorAll('a').forEach(a=>a.addEventListener('click',closeMenu));
document.addEventListener('keydown',e=>{if(e.key==='Escape')closeMenu();});
matchMedia('(min-width: 961px)').addEventListener('change',e=>{if(e.matches)closeMenu();});

document.querySelector('form').addEventListener('submit',e=>{e.preventDefault(); const form=e.currentTarget;const chosen=form.elements.model.selectedOptions[0].textContent;form.querySelector('.form-feedback').textContent=`Поля заповнено. Обрана модель: ${chosen}. Це тестова форма: заявку не надіслано. Для консультації зателефонуйте або напишіть компанії.`;});

const thumbs=[...document.querySelectorAll('.gallery-thumb')];let currentIndex=0;
function setImage(i){currentIndex=(i+thumbs.length)%thumbs.length;const current=thumbs[currentIndex];const main=document.querySelector('.gallery-current');if(main){main.src=current.dataset.src;main.alt=`${product.name} — фото ${currentIndex+1}`;}document.querySelector('.gallery-counter').textContent=`${String(currentIndex+1).padStart(2,'0')} / ${String(thumbs.length).padStart(2,'0')}`;thumbs.forEach((b,j)=>{b.classList.toggle('active',j===currentIndex);b.setAttribute('aria-pressed',String(j===currentIndex));});}
thumbs.forEach((b,i)=>b.addEventListener('click',()=>setImage(i)));
const dialog=document.querySelector('.lightbox');let videoMode=false;
function showDialogImage(){dialog.querySelector('.lightbox-content').innerHTML=image(thumbs[currentIndex].dataset.src,product.name+' — збільшене фото');dialog.querySelector('.lightbox-caption').textContent=`${product.name} · ${currentIndex+1} / ${thumbs.length}`;}
document.querySelector('.gallery-enlarge')?.addEventListener('click',()=>{videoMode=false;showDialogImage();dialog.classList.remove('video-mode');dialog.showModal();document.body.classList.add('dialog-open');});
function closeDialog(){dialog.close();}
dialog.querySelector('.lightbox-close').addEventListener('click',closeDialog);
dialog.addEventListener('close',()=>{dialog.querySelector('.lightbox-content').innerHTML='';document.body.classList.remove('dialog-open');});
dialog.addEventListener('click',e=>{if(e.target===dialog)closeDialog();});
function moveImage(step){if(!videoMode&&thumbs.length){setImage(currentIndex+step);showDialogImage();}}
dialog.querySelector('.lightbox-prev').addEventListener('click',()=>moveImage(-1));dialog.querySelector('.lightbox-next').addEventListener('click',()=>moveImage(1));
dialog.addEventListener('keydown',e=>{if(e.key==='ArrowLeft')moveImage(-1);if(e.key==='ArrowRight')moveImage(1);});
document.querySelector('.video-button')?.addEventListener('click',e=>{videoMode=true;dialog.classList.add('video-mode');dialog.querySelector('.lightbox-content').innerHTML=`<iframe title="Відео ${product.name}" src="${esc(e.currentTarget.dataset.video)}" allow="fullscreen; encrypted-media; picture-in-picture" allowfullscreen></iframe>`;dialog.querySelector('.lightbox-caption').textContent='Відео з оригінальної сторінки моделі';dialog.showModal();document.body.classList.add('dialog-open');});

if(!matchMedia('(prefers-reduced-motion: reduce)').matches&&'IntersectionObserver' in window){const observer=new IntersectionObserver(entries=>{entries.forEach(entry=>{if(entry.isIntersecting){entry.target.classList.add('visible');observer.unobserve(entry.target);}});},{threshold:.08});document.querySelectorAll('.reveal').forEach(el=>{el.classList.add('will-reveal');observer.observe(el);});}
if(location.hash){requestAnimationFrame(()=>document.querySelector(location.hash)?.scrollIntoView());}
